exercises.solutionCode:
class Entity:
    var health: int

    func _init(starting_health: int):
        health = starting_health

    func take_damage(amount: int) -> int:
        health = max(0, health - amount)
        return health

class Player:
    var entity
    var shield: int

    func _init(starting_health: int, starting_shield: int):
        entity = Entity.new(starting_health)
        shield = starting_shield

    func defend(amount: int) -> int:
        var absorbed = min(amount, shield)
        shield -= absorbed
        return entity.take_damage(amount - absorbed)

var player = Player.new(starting_health, starting_shield)
print(player.defend(incoming_damage))
